from utils.logger import log_event


def verify_credentials(user, password, db):
    # Validate input types
    if not isinstance(db, dict) or not isinstance(user, str) or not isinstance(password, str):
        log_event("malformed_input", user if isinstance(user, str) else None)
        raise ValueError("Malformed input")

    if user not in db:
        log_event("login_failed", user)
        return False

    if db[user].get("password") != password:
        log_event("login_failed", user)
        return False

    return True
